    /// `enumArg` for a required argument: absent, null and empty are all
    /// `requiredString`'s "Missing required argument".
    func requiredEnumArg<T: RawRepresentable & CaseIterable>(
        _ a: [String: Any], _ key: String, _ type: T.Type
