            throw ToolError(message: "\(key) must be an array of whole numbers.")
        }
        var values: [Int] = []
        for value in array {
            guard let number = Self.numeric(value), let int = Self.whole(number) else {
                throw ToolError(message: "\(key) must contain whole numbers only.")
            }
