    /// Removes a track. Refuses on a track that still holds clips unless
    /// `with_clips`, which removes those clips with it, and refuses to
    /// remove the LAST track: a project always has somewhere to put a clip,
    /// and an empty track stack is a UI with nothing to drop onto.
    ///
    /// Both refusals carry their own sentence. The last-track one is asked
    /// FIRST, because `with_clips: true` is the way past the other and past
    /// this one it is not: a caller told about the clips would send it and
    /// be refused again.
    ///
    /// `Err` only for an unknown track.
    pub fn remove_track(&self, track: u32, with_clips: bool) -> Result<Outcome, String> {
        self.require_track(track)?;
        if self.tracks.len() <= 1 {
            return Ok(Outcome::Refused(format!(
                "track {track} is the only track left, and a project must always have one"
            )));
        }
        let held: Vec<u32> = self
            .clips
            .iter()
            .filter(|c| c.track == track)
            .map(|c| c.id)
            .collect();
        if !held.is_empty() && !with_clips {
            return Ok(Outcome::Refused(format!(
                "track {track} still holds {}; pass with_clips: true to remove the track \
                 and its clips",
                clip_list(&held)
            )));
        }

        let mut next = self.clone();
        next.tracks.retain(|t| t.id != track);
        next.clips.retain(|c| c.track != track);
        self.finish(next)
    }

    /// Moves a track to `index` in the stack (0 = back-most), sliding the
    /// tracks it passes over the other way — the layer reorder the timeline
    /// drag makes (spec §6).
    ///
    /// `Err` for an unknown track or an index past the end; an identity
    /// when the track is already there.
    func newTrackCommand() {
        guard let document = document else { return }
        document.applyEdit(
            "New Track", .addTrack(index: document.editedProject.snapshot.tracks.count))
    }

    /// A non-empty track refuses to go without `with_clips`, so the clips it
    /// would take go in the question rather than in a beep. `id` is the
    /// track context menu's clicked track; Track ▸ Remove Track passes none
    /// and acts on `currentTrack`.
    func removeTrackCommand(_ id: UInt32? = nil) {
        let track: TrackSnapshot?
        if let id = id {
            track = document?.editedProject.snapshot.track(id)
        } else {
            track = currentTrack
        }
        guard let document = document, let track = track else {
            NSSound.beep()
            return
        }
        let clips = document.editedProject.snapshot.clips(onTrack: track.id)
        guard !clips.isEmpty else {
            document.applyEdit("Remove Track", .removeTrack(track: track.id))
            return
        }
        guard let window = view.window else {
            NSSound.beep()
            return
        }
        let alert = NSAlert()
        alert.messageText = "Remove “\(track.name)”?"
        alert.informativeText =
            clips.count == 1
            ? "The track still holds 1 clip, which will be removed with it."
            : "The track still holds \(clips.count) clips, which will be removed with it."
        alert.addButton(withTitle: "Remove")
        alert.addButton(withTitle: "Cancel")
        alert.beginSheetModal(for: window) { [weak document] response in
            guard response == .alertFirstButtonReturn, let document = document else { return }
            // A sheet's completion is not an AppKit event: the grouped entry
            // point is mandatory here (app/CLAUDE.md's undo pitfall).
            document.performGroupedEdit(
                "Remove Track", [.removeTrack(track: track.id, withClips: true)])
        }
    }

    func removeEmptyTracksCommand() {
        document?.applyEdit("Remove Empty Tracks", .removeEmptyTracks())
    }

