  - to {"description": "Where on the TIMELINE to stop reading, in ticks, snapped to frames; the timeline's end by default. Must be after from.", "type": "integer"}
  - tracks {"items": {"type": "integer"}, "type": "array", "description": "Only the words playing on these timeline tracks (ids from get_project); every track by default."}
  - language {"description": "A language tag, e.g. en-US, for this Mac's recogniser only (a cached transcript answers in its own language). This Mac's own language by default; each language is kept apart in the cache. A tag speech recognition does not know is refused with the tags it knows, and one whose on-device model is not installed is refused as not installed \u2014 this tool never downloads.", "type": "s
  - project {"type": "string", "description": "Path of the open project to act on, as get_project reports it; omit for the frontmost one."}
